actions.script:
import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import java.security.MessageDigest

ec.logger.info("[PROCESS#PAYLOAD] context: ${context}")
// 1. Map mode string to enumId
Map modeMap = [
    'plan': 'AamPlan', 'build': 'AamBuild', 'orchestrate': 'AamOrchestrate',
    'test': 'AamTest', 'query': 'AamQuery', 'history': 'AamHistory', 'discuss': 'AamDiscuss'
]
String modeEnumId = modeMap.get(mode.toLowerCase()) ?: 'AamPlan'

// 2. Normalize and compute content hash
Map rawPayloadMap = payload ?: [:]
if (userPromptText) rawPayloadMap.userPromptText = userPromptText
String payloadJsonStr = JsonOutput.toJson(rawPayloadMap)

MessageDigest md = MessageDigest.getInstance("SHA-256")
String sha256Hex = md.digest(payloadJsonStr.getBytes("UTF-8")).encodeHex().toString()

// 3. Resolve or create AgiArtifact
String artId = null
if (artifactUri) {
    def artVal = ec.entity.find("org.moqui.ai.AgiArtifact").condition("artifactPath", artifactUri).one()
    if (!artVal) {
        artVal = ec.entity.makeValue("org.moqui.ai.AgiArtifact")
        artVal.artifactPath = artifactUri
        artVal.artifactStatusEnumId = "AasDraft"
        artVal.setSequencedIdPrimary()
        artVal.create()
    }
    artId = artVal.agiArtifactId
}

// 4. Create or Update AgiPayload entity
def payloadVal = agiPayloadId ? ec.entity.find("org.moqui.ai.payload.AgiPayload").condition("agiPayloadId", agiPayloadId).one() : null
if (!payloadVal) {
    payloadVal = ec.entity.makeValue("org.moqui.ai.payload.AgiPayload")
    payloadVal.setSequencedIdPrimary()
    payloadVal.createdDate = ec.user.nowTimestamp
    payloadVal.statusId = "PlsDraft"
} else {
    payloadVal.revisionNumber = (payloadVal.revisionNumber ?: 1) + 1
}

payloadVal.modeEnumId = modeEnumId
payloadVal.targetComponent = targetComponent
payloadVal.artifactUri = artifactUri
payloadVal.targetMariaId = targetMariaId
payloadVal.agiArtifactId = artId
payloadVal.title = title ?: (userPromptText ? (userPromptText.length() > 50 ? userPromptText.substring(0, 47) + "..." : userPromptText) : "Untitled Payload")
payloadVal.userPromptText = userPromptText
payloadVal.payloadJsonData = payloadJsonStr
payloadVal.contentSha256 = sha256Hex
payloadVal.lastUpdatedStamp = ec.user.nowTimestamp

// 5. Contextual Intent Promotion: Map Prompt -> WorkEffort Intent Node
if (["AamBuild", "AamTest", "AamDiscuss"].contains(modeEnumId) && artId) {
    String weType = modeEnumId == "AamDiscuss" ? "WetDiscussion" : "WetIntent"
    String safeMariaId = targetMariaId ?: (artifactUri ? org.moqui.ide.ScreenEditorServices.generateMariaId(artifactUri, "root") : null)

    Map weResult = ec.service.sync().name("org.moqui.ide.BlueprintServices.create#WorkEffortNode").parameters([
        workEffortName: payloadVal.title,
        agiArtifactId: artId,
        sourceReferenceId: artifactUri,
        workEffortTypeEnumId: weType,
        targetMariaId: safeMariaId
    ]).call()

    payloadVal.workEffortId = weResult.workEffortId
}

payloadVal.createOrUpdate()
context.agiPayloadId = payloadVal.agiPayloadId
context.workEffortId = payloadVal.workEffortId

// 6. Persist key-value Facets
if (facets instanceof Map) {
    facets.each { k, v ->
        if (k && v != null) {
            def facetVal = ec.entity.makeValue("org.moqui.ai.payload.AgiPayloadFacet")
            facetVal.setSequencedIdPrimary()
            facetVal.agiPayloadId = payloadVal.agiPayloadId
            facetVal.facetKey = k.toString()
            facetVal.facetValue = v.toString()
            facetVal.create()
        }
    }
}

// 7. Mode-Specific Pipeline Execution
Map execResult = [:]
if (modeEnumId == "AamBuild") {
    // Execute staged AST mutation if present in payload
    if (rawPayloadMap.stagedAstMutation && artifactUri) {
        payloadVal.statusId = "PlsExecuting"
        payloadVal.update()

        String astJson = JsonOutput.toJson(rawPayloadMap.stagedAstMutation)
        ec.service.sync().name("org.moqui.ide.AgiWorkspaceServices.store#WorkspaceBuffer")
            .parameters([artifactUri: artifactUri, metaJsonBuffer: astJson])
            .call()
        ec.service.sync().name("org.moqui.ide.AgiWorkspaceServices.save#ScreenXml")
            .parameters([artifactUri: artifactUri, metaJsonBuffer: astJson])
            .call()

        payloadVal.statusId = "PlsCommitted"
        execResult.status = "SUCCESS"
        execResult.message = "Successfully applied AST mutation to ${artifactUri}"
    } else {
        payloadVal.statusId = "PlsStaged"
        execResult.status = "STAGED"
        execResult.message = "Build payload staged for AI assistant code generation."
    }
} else if (modeEnumId == "AamTest") {
    payloadVal.statusId = "PlsStaged"
    execResult.status = "READY"
    execResult.message = "Test payload ready for execution in test harness."
} else {
    payloadVal.statusId = "PlsDraft"
    execResult.status = "RECORDED"
    execResult.message = "Payload context and intent saved."
}

payloadVal.executionResultJson = JsonOutput.toJson(execResult)
payloadVal.update()

context.statusId = payloadVal.statusId
context.executionResult = execResult

import groovy.json.JsonSlurper

def pld = ec.entity.find("org.moqui.ai.payload.AgiPayload").condition("agiPayloadId", agiPayloadId).one()
if (!pld) {
    ec.message.addError("AgiPayload not found for ID: ${agiPayloadId}")
    return
}

Map outMap = pld.getMap()
if (pld.payloadJsonData) {
    try {
        outMap.payload = new JsonSlurper().parseText(pld.payloadJsonData)
    } catch (Exception ignore) {}
}
if (pld.executionResultJson) {
    try {
        outMap.executionResult = new JsonSlurper().parseText(pld.executionResultJson)
    } catch (Exception ignore) {}
}

def facets = ec.entity.find("org.moqui.ai.payload.AgiPayloadFacet").condition("agiPayloadId", agiPayloadId).list()
outMap.facets = facets.collectEntries { [(it.facetKey): it.facetValue] }

context.payloadDetails = outMap

                import groovy.json.JsonSlurper
                import org.moqui.resource.ResourceReference

                StringBuilder instructionBuffer = new StringBuilder()

                // Helper: safely fetch resource text
                def loadResourceText = { String loc ->
                    if (!loc) return null
                    try {
                        ResourceReference rr = ec.resource.getLocationReference(loc)
                        if (rr != null && rr.getExists()) {
                            return rr.getText()
                        }
                    } catch (Exception e) {
                        ec.logger.warn("⚠️ [assemble#SystemInstruction] Failed to read resource at ${loc}: ${e.message}")
                    }
                    return null
                }

                // 1. Load Registry Configuration
                String registryLocation = "component://agi-ai/mcp/manifests/ArtifactTypeRegistry.json"
                String registryJson = loadResourceText(registryLocation)
                Map registry = [:]
                if (registryJson) {
                    try {
                        registry = new JsonSlurper().parseText(registryJson) as Map
                    } catch (Exception e) {
                        ec.logger.error("❌ Failed to parse ArtifactTypeRegistry.json: ${e.message}", e)
                    }
                }

                // 2. Layer 1: System Base Instruction
                String baseLoc = "component://agi-ai/mcp/instructions/base/SystemBaseInstruction.md"
                String baseText = loadResourceText(baseLoc)
                if (baseText) {
                    instructionBuffer.append(baseText.trim())
                    instructionBuffer.append("\n\n")
                } else {
                    ec.logger.warn("⚠️ [assemble#SystemInstruction] SystemBaseInstruction.md not found at ${baseLoc}")
                }

                // 3. Layer 2: Determine Artifact Type & Append Specific Instruction
                String matchedTypeKey = "XML_SCREEN" // sensible default
                Map matchedConfig = null
                Map artifactTypes = (registry.artifactTypes ?: [:]) as Map

                for (entry in artifactTypes) {
                    Map typeDef = entry.value as Map
                    List patterns = (typeDef.fileMatchPatterns ?: []) as List

                    boolean matches = patterns.any { pattern ->
                        try {
                            return java.util.regex.Pattern.compile(pattern.toString()).matcher(artifactUri).find()
                        } catch (Exception pe) {
                            return false
                        }
                    }

                    if (matches) {
                        matchedTypeKey = typeKey
                        matchedConfig = typeDef
                        break
                    }
                }

                if (!matchedConfig && artifactTypes.containsKey("XML_SCREEN")) {
                    matchedConfig = artifactTypes.get("XML_SCREEN") as Map
                }

                if (matchedConfig) {
                    String artifactInstructionLoc = matchedConfig.instructionUri
                    String artifactText = loadResourceText(artifactInstructionLoc)
                    if (artifactText) {
                        instructionBuffer.append("<!-- ============================================================= -->\n")
                        instructionBuffer.append("<!-- ARTIFACT DIRECTIVES: ${matchedTypeKey} -->\n")
                        instructionBuffer.append("<!-- ============================================================= -->\n")
                        instructionBuffer.append(artifactText.trim())
                        instructionBuffer.append("\n\n")
                    }
                    context.schemaUri = matchedConfig.schemaUri
                    context.editorComponent = matchedConfig.editorComponent
                }
                context.detectedArtifactType = matchedTypeKey

                // 4. Layer 2.5: Mode-Specific Operational Directives (Step C)
                String normalizedMode = (mode ?: 'build').toLowerCase().trim()
                instructionBuffer.append("<!-- ============================================================= -->\n")
                instructionBuffer.append("<!-- CURRENT OPERATION MODE: ${normalizedMode.toUpperCase()} -->\n")
                instructionBuffer.append("<!-- ============================================================= -->\n")

                if (normalizedMode == 'plan') {
                    instructionBuffer.append("""### OPERATIONAL DIRECTIVE: PLAN MODE
- You are strictly operating as an Architectural Formulator and Planner.
- DO NOT generate complete runnable XML files, and DO NOT invoke file mutation tools.
- Output ONLY an architectural design specification in your message response.
- In your JSON response envelope, set "rawXmlContent": null, "astTree": null.
- Provide a clear, structured Markdown breakdown including:
  1. High-level architecture and Mantle UDM entity mappings (e.g. mantle.party.Party, Person, etc.).
  2. UI layout structure, forms, tables, and container hierarchy.
  3. Security and HIPAA compliance rules enforced.
  4. Numbered, step-by-step implementation tasks ready for execution in BUILD mode.
""")
                } else if (normalizedMode == 'discuss') {
                    instructionBuffer.append("""### OPERATIONAL DIRECTIVE: DISCUSS MODE
- You are acting as an architectural peer discussing Intent, Trade-offs, and Architectural Decision Records (ADRs).
- DO NOT generate raw XML screen markup or mutate files.
- In your JSON response envelope, set "rawXmlContent": null, "astTree": null.
- Clarify domain rules, entity modeling choices, and state transitions collaboratively.
""")
                } else if (normalizedMode == 'test') {
                    instructionBuffer.append("""### OPERATIONAL DIRECTIVE: TEST MODE
- You are generating declarative test verification suites and assertions.
- Adhere strictly to the TestPayload schema and Moqui test assertion syntax.
""")
                } else {
                    // Default / Build Mode
                    instructionBuffer.append("""### OPERATIONAL DIRECTIVE: BUILD MODE
- You are actively mutating or generating software artifacts.
- Produce production-grade, syntactically clean declarative Moqui XML matching the specified schemas.
- Provide the complete artifact markup in "rawXmlContent" or call the appropriate mutation tool.
""")
                }
                instructionBuffer.append("\n\n")

                // 5. Layer 3: Dynamic Facet Overlays
                Map facetMap = (facets ?: [:]) as Map
                Map facetInstructionMap = (registry.facetInstructionMap ?: [:]) as Map

                facetInstructionMap.each { facetKey, mappingObj ->
                    String expectedVal = mappingObj.conditionValue?.toString()
                    String instructionLoc = mappingObj.instructionUri?.toString()
                    String actualVal = facetMap.get(facetKey)?.toString()

                    if (expectedVal != null && actualVal != null && expectedVal.equalsIgnoreCase(actualVal)) {
                        String facetText = loadResourceText(instructionLoc)
                        if (facetText) {
                            instructionBuffer.append("<!-- ============================================================= -->\n")
                            instructionBuffer.append("<!-- COMPLIANCE FACET OVERLAY: ${facetKey}=${actualVal} -->\n")
                            instructionBuffer.append("<!-- ============================================================= -->\n")
                            instructionBuffer.append(facetText.trim())
                            instructionBuffer.append("\n\n")
                        }
                    }
                }

                context.systemInstruction = instructionBuffer.toString().trim()

import groovy.json.JsonSlurper
import org.moqui.resource.ResourceReference

String regLoc = "component://agi-ai/mcp/manifests/ArtifactTypeRegistry.json"
ResourceReference rr = ec.resource.getLocationReference(regLoc)
Map registry = [:]
if (rr != null && rr.getExists()) {
    try {
        registry = new JsonSlurper().parseText(rr.getText()) as Map
    } catch (Exception e) {
        ec.logger.error("❌ Failed to parse ArtifactTypeRegistry: ${e.message}")
    }
}

Map artifactTypes = (registry.artifactTypes ?: [:]) as Map
String matchedKey = "XML_SCREEN"
Map matchedConfig = artifactTypes.get("XML_SCREEN") as Map

for (entry in artifactTypes) {
    Map typeDef = entry.value as Map
    List patterns = (typeDef.fileMatchPatterns ?: []) as List
    boolean matches = patterns.any { p ->
        try {
            return java.util.regex.Pattern.compile(p.toString()).matcher(artifactUri).find()
        } catch (Exception pe) {
            return false
        }
    }
    if (matches) {
        matchedKey = entry.key
        matchedConfig = typeDef
        break
    }
}

context.artifactType = matchedKey
context.typeName = matchedConfig?.typeName ?: matchedKey
context.schemaUri = matchedConfig?.schemaUri
context.editorComponent = matchedConfig?.editorComponent ?: "agi-screen-payload-editor"
context.groundingPanels = matchedConfig?.groundingPanels ?: []
